      });

      testScheduler.flush();
      // Requests are made at times tm and ta
      expect(requestSpy.callCount).to.equal(2);
      // No request cancellation is effected, as unsubscription occurs before rescheduling
      expect(cancelSpy.callCount).to.equal(0);
    });
