        return parseTime(prefix + '|');
    };
    const lowerCaseO = (...values) => {
        const source = {
            subscribe(observer) {
                const destination = typeof observer === 'function' ? { next: observer } : observer;
                for (const value of values)
                    destination.next?.(value);
                destination.complete?.();
                return { unsubscribe() { } };
            }
        };
        const observableKey = Symbol.observable ?? '@@observable';
        source[observableKey] = function () { return this; };
        return source;
    };
    await rxTest(async ({ expectObservable, cold: __rxCold, hot: __rxHot, time: __rxTime, flush: __rxFlush, now: __rxNow, schedule: __rxSchedule }) => {
        const e1 = lowerCaseO('a', 'b', 'c');
