      const expected2 = '      -----1-2-3----4-(4|)    ';
      const subscriber3 = hot('--------c|              ').pipe(mergeMapTo(multicasted));
      const expected3 = '      ---------1-2-3----4-(4|)';

      expectObservable(subscriber1).toBe(expected1);
      expectObservable(subscriber2).toBe(expected2);
