async function migrated(runtime) {
const { rxTest, applyOperators, onErrorResumeNext } = runtime;
    const __subscriptionFrame = (marbles, marker, parseTime) => {
        const markerIndex = marbles.indexOf(marker);
        if (markerIndex < 0)
            return Infinity;
        const prefix = marbles.slice(0, markerIndex).replace(/[!^]/g, '-');
        return parseTime(prefix + '|');
    };
    const asInteropObservable = (source) => new Proxy(source, {
        get(target, key) {
            if (key === 'subscribe') {
                return (...args) => Reflect.apply(target.subscribe, target, args);
            }
            return Reflect.get(target, key, target);
        },
        getPrototypeOf(target) {
            const prototype = Reflect.getPrototypeOf(target);
            return { ...prototype, subscribe: (...args) => Reflect.apply(target.subscribe, target, args) };
        }
    });
    await rxTest(async ({ cold, hot, expectObservable, expectSubscriptions, cold: __rxCold, hot: __rxHot, time: __rxTime, flush: __rxFlush, now: __rxNow, schedule: __rxSchedule }) => {
        const e1 = hot('  --a--b--#       ');
        const e1subs = '  ^-------!       ';
        const e2 = cold('         --c--d--');
        const e2subs = '  --------^---!   ';
        const unsub = '   ------------!   ';
        const expected = '--a--b----c--   ';
        // This test manipulates the observable to make it look like an interop
        // observable - an observable from a foreign library. Interop subscribers
        // are treated differently: they are wrapped in a safe subscriber. This
        // test ensures that unsubscriptions are chained all the way to the
        // interop subscriber.
        expectObservable(applyOperators(e1, [onErrorResumeNext(asInteropObservable(e2))]), unsub).toBe(expected);
        expectSubscriptions(e1.subscriptions).toBe(e1subs);
        expectSubscriptions(e2.subscriptions).toBe(e2subs);
    });
}

