async function migrated(runtime) {
const { rxTest, applyOperators, expect, scan, finalize } = runtime;
    const __subscriptionFrame = (marbles, marker, parseTime) => {
        const markerIndex = marbles.indexOf(marker);
        if (markerIndex < 0)
            return Infinity;
        const prefix = marbles.slice(0, markerIndex).replace(/[!^]/g, '-');
        return parseTime(prefix + '|');
    };
    await rxTest(async ({ hot, expectObservable, expectSubscriptions, cold: __rxCold, hot: __rxHot, time: __rxTime, flush: __rxFlush, now: __rxNow, schedule: __rxSchedule }) => {
        // prettier-ignore
        const values = {
            a: 1, b: 3, c: 5,
            x: 1, y: 4, z: 9,
        };
        let idx = [0, 1, 2];
        const e1 = hot('  --a--b--c--|', values);
        const e1subs = '  ^----------!';
        const expected = '--x--y--z--|';
        const scanFunction = (o, value, index) => {
            expect(index).to.equal(idx.shift());
            return o + value;
        };
        const scanObs = applyOperators(e1, [scan(scanFunction, 0),
            finalize(() => {
                expect(idx).to.be.empty;
            })]);
        expectObservable(scanObs).toBe(expected, values);
        expectSubscriptions(e1.subscriptions).toBe(e1subs);
    });
}

