        const markerIndex = marbles.indexOf(marker);
        if (markerIndex < 0)
            return Infinity;
        const prefix = marbles.slice(0, markerIndex).replace(/[!^]/g, '-');
        return parseTime(prefix + '|');
    };
    const asInteropObservable = (source) => new Proxy(source, {
        get(target, key) {
            if (key === 'subscribe') {
                return (...args) => Reflect.apply(target.subscribe, target, args);
            }
            return Reflect.get(target, key, target);
        },
        getPrototypeOf(target) {
            const prototype = Reflect.getPrototypeOf(target);
            return { ...prototype, subscribe: (...args) => Reflect.apply(target.subscribe, target, args) };
        }
    });
    await rxTest(async ({ hot, cold, expectObservable, expectSubscriptions, cold: __rxCold, hot: __rxHot, time: __rxTime, flush: __rxFlush, now: __rxNow, schedule: __rxSchedule }) => {
