async function migrated(runtime) {
const { rxTest, applyOperators, expect, timeout, TimeoutError } = runtime;
    const __subscriptionFrame = (marbles, marker, parseTime) => {
        const markerIndex = marbles.indexOf(marker);
        if (markerIndex < 0)
            return Infinity;
        const prefix = marbles.slice(0, markerIndex).replace(/[!^]/g, '-');
        return parseTime(prefix + '|');
    };
    const defaultTimeoutError = new TimeoutError();
    await rxTest(async ({ cold, time, cold: __rxCold, hot: __rxHot, time: __rxTime, expectObservable, flush: __rxFlush, now: __rxNow, schedule: __rxSchedule }) => {
        const e1 = cold('-------a--b--|');
        const t = time(' -----|');
        const result = applyOperators(e1, [timeout(t)]);
        let error;
        result.subscribe({
            next: () => {
                throw new Error('this should not next');
            },
            error: (err) => {
                error = err;
            },
            complete: () => {
                throw new Error('this should not complete');
            },
        });
        await __rxFlush();
        expect(error).to.be.an.instanceof(TimeoutError);
        expect(error).to.have.property('name', 'TimeoutError');
        expect(error.info).to.deep.equal({
            seen: 0,
            meta: null,
            lastValue: null,
        });
    });
}

